function createPool(size, scriptUrl) {
  const workers = Array.from({ length: size }, () => new Worker(scriptUrl));
  const queue = [];
  const busy = new Set();

  function dispatch(worker) {
    const job = queue.shift();
    if (!job) { busy.delete(worker); return; }
    busy.add(worker);
    worker.onmessage = (e) => {
      job.resolve(e.data);
      dispatch(worker);
    };
    worker.postMessage(job.payload);
  }

  return {
    run(payload) {
      return new Promise((resolve) => {
        queue.push({ payload, resolve });
        const idle = workers.find((w) => !busy.has(w));
        if (idle) dispatch(idle);
      });
    },
  };
}

